using System;

class Animal {
    public virtual void HacerSonido() {
        Console.WriteLine("Sonido genérico");
    }
}

class Perro : Animal {
    public override void HacerSonido() {
        Console.WriteLine("Guau");
    }
}

class Program {
    static void Main() {
        Animal a = new Perro();
        a.HacerSonido();
    }
